import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // ---------- Text ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  for (const item of textItems) {
    const fontSize = (item.typography?.fontSize) || 31;
    const color = (config.intent?.visualSpec?.colors?.ink) || '#16161d';
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color,
      align: 'left',
    });
    textGroup.add(txt);
  }
  root.add(textGroup);

  // ---------- Textured Plane ----------
  const plane = new Mesh(
    new PlaneGeometry(3.2, 2.0),
    new MeshBasicNodeMaterial()
  );
  root.add(plane);

  // Load texture asynchronously (no await)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      plane.material.map = tex;
      plane.material.needsUpdate = true;
    });
  }

  // ---------- Cinematic Primitives ----------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name];
      if (handler) {
        const result = handler(root, prim.params);
        primitiveHandles.push(result);
      }
    }
  }

  // ---------- Event Handlers ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose primitives
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') ph.cleanup();
    }

    // Dispose plane resources
    if (plane.geometry) plane.geometry.dispose();
    if (plane.material) {
      if (plane.material.map) plane.material.map.dispose();
      plane.material.dispose();
    }

    // Dispose text resources
    textGroup.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });

    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
